import{_ as t,o as i,c as r,a2 as a}from"./chunks/framework.mrTIYZc5.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"DSO Documentation","text":"Secrets for Docker — Local to Cloud","tagline":"Inject secrets at runtime without storing them on disk. Use local encrypted vaults or cloud providers with the same workflow.","image":{"src":"/logo/dso-primary-logo.svg","alt":"DSO Logo"},"actions":[{"theme":"brand","text":"Introduction","link":"/guide/what-is-dso"},{"theme":"alt","text":"Quickstart","link":"/guide/getting-started"}]},"features":[{"title":"Dual-Mode Execution","details":"Seamlessly switch between Local Mode (Native AES-256 Vault) and Cloud Mode (AWS, Azure, Huawei) with automatic detection.","icon":"⚡"},{"title":"Secret Isolation","details":"All secret values are held in-memory and injected via Unix socket. Zero persistence to disk as plaintext.","icon":"🔒"},{"title":"Verified Plugins","details":"Selective, SHA256-verified plugin installation. Only install what you need, with full integrity checks.","icon":"🛡️"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),o={name:"index.md"};function n(s,e,l,c,d,u){return i(),r("div",null,[...e[0]||(e[0]=[a('<h2 id="why-dso" tabindex="-1">Why DSO? <a class="header-anchor" href="#why-dso" aria-label="Permalink to &quot;Why DSO?&quot;">​</a></h2><p>Docker Secret Operator (DSO) addresses a critical gap in infrastructure security: the management of sensitive credentials in non-Kubernetes environments. While Kubernetes has a mature ecosystem for secret orchestration, standalone Docker Engine deployments often rely on insecure <code>.env</code> files or manual, friction-heavy procedures.</p><p>DSO provides a Kubernetes-grade control loop for Docker Engine. It ensures that secrets are fetched from high-assurance vaults (like AWS Secrets Manager or HashiCorp Vault) and injected directly into target containers with Zero-Persistence. This means your secrets never touch the host filesystem, providing a strictly ephemeral and auditable lifecycle.</p><h3 id="core-security-pillars" tabindex="-1">Core Security Pillars: <a class="header-anchor" href="#core-security-pillars" aria-label="Permalink to &quot;Core Security Pillars:&quot;">​</a></h3><ul><li>Zero Persistence: Secrets reside only in process RAM and target container memory-mapped filesystems.</li><li>Event-Driven: Immediate reconciliation of container lifecycle events.</li><li>Provider Agnostic: Standardized interface for AWS, Azure, Huawei Cloud, and HashiCorp Vault.</li><li>Operations First: Built-in strategy engine for rolling updates and atomic shifts.</li></ul>',5)])])}const p=t(o,[["render",n]]);export{m as __pageData,p as default};
